P=Path('/mnt/BioDisk/wangmingyuan/lung_CD4T_MRE11A_scRNA');O=P/'11_reports/four_axis_screen_20261017_v15';T=O/'inputs/decontx_diagnostic';T.mkdir(exist_ok=True)
plan={'purpose':'final source credibility diagnostic for sole data-intersection DUSP5; not rescreening','trigger':'CDH1/OCLN source co-detection of epithelial markers; BMP1 and H2-Q1 predominantly 1UMI','model':'decontX on full-lung raw counts independently per sample, frozen Broad plus existing fine CD4/Mac labels; no empty droplet background available in this input','seed':42,'maxIter':500,'outputs':'raw and corrected candidate/source CP10k, candidate/program association and source-candidate associations; all six mice','thresholds':'no new candidate-selection cutoff; preserve original screen and disclose whether model correction changes source interpretation','limitation':'model estimate depends on labels; not independent evidence of endogenous expression'}
