f=P/'02_analysis/GSE314943/stage3_20260905_214228_VPtd0r/objects/whole_annotated.h5ad';a=ad.read_h5ad(f);meta=a.obs.copy();meta['cell']=a.obs_names.astype(str);meta['decontx_cluster']=meta.Broad.astype(str)
